"""Additional original guidance, examples and practical checklists."""
GUIDE_DETAILS = {
 'guide-youth-leap-vs-savings': {
  'reader':'이미 청년도약계좌에 가입했고 납입액을 조정하거나 만기까지 유지할지 고민하는 분을 위한 글이에요.',
  'extra':[
   ('통장 잔액과 비교용 계산 결과가 다른 이유', '실제 계좌에는 이미 납입한 날짜별 원금과 가입 시점의 금리·기여금 규정이 반영돼 있어요. 이 사이트의 계산은 같은 월 납입액과 금리를 60개월 유지한다고 놓은 비교예요. 현재 잔액을 그대로 불려주는 기능은 아니므로 계산 합계를 은행이 보장하는 만기액으로 해석하면 안 돼요.'),
   ('납입액을 정할 때 먼저 볼 것', '최대 기여금만 보기보다 매달 유지할 수 있는 납입액부터 정해 보세요. 월세·대출상환·생활비를 뺀 뒤에도 비상자금을 유지할 수 있는지 확인하는 과정이 필요해요. 납입액을 바꿨을 때 원금 증가와 기여금 증가를 나눠 보면 적금에 묶이는 돈의 규모를 더 쉽게 이해할 수 있어요.'),
   ('새로 가입할 상품을 찾는 경우', '청년도약계좌 신규 가입은 종료됐으므로 기존 가입자 안내를 신규 모집 공고로 착각하지 마세요. 청년미래적금 등 다른 상품은 만기·납입한도·정부기여금·가구소득 심사가 다를 수 있어요. 기존 계좌를 먼저 해지하기보다 전환 가능 여부와 신청 일정부터 공식 안내에서 확인하세요.')],
  'example_title':'월 납입액에 따른 기여금 비교 · 총급여 2,400만원 이하 구간',
  'example':[('10만원 납입','100,000원 × 6% = 월 6,000원'),('40만원 납입','400,000원 × 6% = 월 24,000원'),('70만원 납입','400,000원 × 6% + 300,000원 × 3% = 월 33,000원')],
  'example_note':'2025년 이후 납입 기여금 구조의 예시예요. 계좌별 유지심사·재가입 조정·실제 납입 이력을 반영한 은행 지급액은 별도로 확인해야 해요.',
  'checklist':['가입 은행과 계좌 개설일, 실제 만기일 확인','기본금리·우대금리와 충족한 우대조건 구분','정부기여금 적용 소득구간 및 유지심사 결과 확인','특별중도해지·부분인출·전환 조건 비교','납입원금과 정부기여금·은행이자를 분리해서 보기'],
  'faq':[('매달 70만원을 넣지 않으면 혜택이 전혀 없나요?','납입한 금액과 해당 소득구간의 매칭 구조에 따라 기여금이 달라져요. 최대 납입액을 채우지 않았다는 이유만으로 기여금이 항상 0원이 되는 것은 아니에요.'),('가입 당시 예상금액과 현재 계산기가 다른데 어느 쪽이 맞나요?','실제 계좌의 가입 조건과 은행의 납입 내역이 기준이에요. 금리·기여금 규정·소득구간을 같은 조건으로 맞춘 뒤 비교해야 원인을 찾을 수 있어요.'),('급하게 돈이 필요하면 바로 해지해야 하나요?','해지 전에 부분인출 가능 여부, 중도해지 금리와 기여금 처리 등을 확인하세요. 이 글은 특정 선택을 권하지 않으며 실제 조건은 가입 은행에서 확인해야 해요.')]},
 'guide-freelancer-tax-return': {
  'reader':'3.3%를 떼고 돈을 받았거나, 지금은 일을 쉬고 있지만 과거 사업소득의 신고·환급 여부가 궁금한 분을 위한 글이에요.',
  'extra':[
   ('실수령액 대신 공제 전 수입부터 확인하세요','통장에 96만7천원이 들어왔다면 100만원에서 3만3천원을 원천징수한 사례일 수 있어요. 실수령액을 다시 총수입으로 넣으면 이미 뗀 세금과 경비 계산이 모두 달라져요. 지급처가 여러 곳이면 해당 연도의 지급명세서와 원천징수 내역을 모아 확인하는 것이 먼저예요.'),
   ('현재 직업과 소득이 발생한 연도를 구분하세요','올해 퇴사했더라도 작년에 사업소득이나 근로소득이 있었다면 그 연도의 신고 내용을 확인할 수 있어요. 학생이거나 취업준비 중이라는 현재 상태만으로 과거의 세금 정산 대상에서 제외되는 것은 아니에요. 반대로 받은 돈의 소득 구분이 사업소득인지 근로소득인지도 먼저 확인해야 해요.'),
   ('정기신고 기한을 놓쳤다면','2025년 귀속 일반 종합소득세 정기신고 기한은 2026년 6월 1일까지였어요. 아직 신고하지 않았다면 홈택스의 기한 후 신고·기한 후 환급신고 안내를 확인하세요. 이미 신고했는데 누락이 있는 경우에는 신고 이력과 수정·경정 관련 절차를 구분해야 하며 이 계산기는 가산세나 기간별 제한을 판단하지 않아요.')],
  'example_title':'원천징수액이 같아도 정산 결과는 달라져요',
  'example':[('공통 가정','사업수입 3,000만원, 원천징수 99만원, 본인 기본공제, 표준세액공제 7만원'),('경비율 60%인 단순 사례','국세·지방세 합계 616,000원 → 환급 차액 374,000원'),('필요경비 0원인 비교 사례','국세·지방세 합계 3,239,500원 → 추가 납부 차액 2,249,500원')],
  'example_note':'계산 차이를 설명하기 위한 가상 사례예요. 실제로 경비율을 마음대로 선택할 수 있다는 뜻은 아니며 다른 종합소득·공제·감면·가산세는 제외했어요.',
  'checklist':['공제 전 총수입과 실제 원천징수세액 대조','소득이 발생한 귀속연도와 지급명세서 확인','업종코드 및 경비율·기장 대상 여부 확인','다른 근로·사업·연금·기타소득 합산 필요 여부 확인','국세 신고 뒤 지방소득세 신고 상태도 확인'],
  'faq':[('3.3%를 냈으면 모두 환급받나요?','아니요. 미리 납부한 세금보다 실제로 계산된 세금이 적을 때 차액이 환급돼요. 필요경비가 적거나 다른 소득이 있으면 추가 납부가 발생할 수도 있어요.'),('모두채움 안내가 오면 검토 없이 제출해도 되나요?','미리 채워진 내역과 실제 지급명세서·다른 소득·공제 대상이 맞는지 확인하는 과정이 필요해요. 안내문이 있다는 사실이 모든 개인 상황을 검증했다는 의미는 아니에요.'),('머니패스에 세금 신고서나 계좌번호를 보내야 하나요?','그럴 필요 없어요. 이 사이트는 모의계산과 안내만 제공해요. 실제 신고와 환급계좌 입력은 국세청 공식 사이트에서 직접 진행해 주세요.')]},
 'guide-unemployment-benefit': {
  'reader':'퇴사했거나 퇴사를 앞두고 구직급여의 지급액·지급일수와 신청 준비 순서를 알고 싶은 일반 근로자를 위한 글이에요.',
  'extra':[
   ('가입기간과 피보험단위기간이 헷갈린다면','소정급여일수를 정하는 가입기간과 수급자격 심사의 피보험단위기간은 역할이 달라요. 단순히 달력상 6개월을 일했다는 이유만으로 180일 요건을 충족한다고 단정할 수 없어요. 유급일수와 이전 사업장 이력, 과거 수급 이력에 따른 합산 범위는 공식 자료로 확인해야 해요.'),
   ('퇴사 전에 챙기면 좋은 자료','고용보험 가입 이력, 임금명세서, 이직 사유를 설명할 자료와 이직확인서 처리 여부를 확인하세요. 자진퇴사의 정당한 사유를 주장하는 경우에는 말로 설명하는 것 외에 어떤 자료가 필요한지 관할 고용센터에서 안내받는 편이 좋아요. 이 글에서 특정 사유의 인정 여부를 확정하지는 않아요.'),
   ('총액을 생활비 계획에 사용할 때','예상 총액을 한 번에 입금되는 돈처럼 쓰면 현금흐름을 잘못 잡을 수 있어요. 회차별 실업인정일수와 입금 시점, 재취업할 가능성을 함께 봐야 해요. 계산기의 28일 환산액도 비교용 값이므로 월세나 대출 상환 일정은 실제 지급 안내와 맞춰 주세요.')],
  'example_title':'2026년 일반 근로자 · 8시간·50세 미만·가입 2년 가상 사례',
  'example':[('1일 평균임금','100,000원, 더 높은 통상임금은 없는 경우'),('평균임금 60%와 하한 비교','60,000원과 66,048원 중 하한액 적용'),('지급일수와 총액','150일 × 66,048원 = 9,907,200원'),('28일 단순 환산','28일 × 66,048원 = 1,849,344원')],
  'example_note':'수급자격 인정과 전체 기간의 실업인정을 가정해요. 일용직·자영업자·예술인·노무제공자 등 별도 산식은 이 사례에 포함되지 않아요.',
  'checklist':['이직일과 이직 사유 확인','고용보험 가입 이력과 피보험단위기간 확인','회사 이직확인서·상실신고 처리 확인','고용24 구직신청·교육 및 관할 센터 안내 확인','실업인정 일정과 재취업활동 기록 관리'],
  'faq':[('자진퇴사라면 알아볼 필요가 없나요?','일반적으로 이직 사유를 심사하며 정당한 사유가 인정되는 자진퇴사 등 예외가 있을 수 있어요. 계산기 금액과 자격 여부를 구분하고 관할 센터에 구체적인 사실관계를 확인해 보세요.'),('50세 구분은 현재 나이로 선택하나요?','지급일수 표는 이직일 당시 연령 기준으로 선택해요. 생일이나 퇴사일을 잘못 잡으면 구간을 잘못 선택할 수 있어요.'),('재취업하면 남은 금액이 모두 지급되나요?','단순히 계산기 총액에서 받은 금액을 뺀 잔액을 모두 받는 구조로 해석하면 안 돼요. 재취업 후 처리와 관련 수당은 개별 요건을 공식 안내에서 확인해 주세요.')]},
 'guide-youth-rent': {
  'reader':'부모와 따로 월세로 거주하는 청년이나, 기존 청년월세 지원을 받은 뒤 다음 신청 가능 여부를 알아보는 분을 위한 글이에요.',
  'extra':[
   ('월세를 얼마 내는지와 지원 대상인지는 다른 문제예요','월세 부담이 크다는 사실만으로 지원 대상이 되는 것은 아니에요. 나이·무주택·가구의 소득과 재산·과거 지원 회차를 함께 확인해야 해요. 공고상 신청 가능한 출생연도와 가구 구성 기준을 먼저 보고, 실제로 인정되는 월세 지출을 그다음 확인해 보세요.'),
   ('청년가구와 원가구를 나눠 보는 이유','독립해 살더라도 부모를 포함한 원가구 심사가 필요한 경우가 있어요. 주민등록상 혼자 산다는 사실이 모든 심사에서 1인 가구만 본다는 뜻은 아니에요. 원가구 심사 예외는 연령·혼인 등 조건에 따라 달라지므로, 임의로 부모 소득을 빼고 판단하지 말고 공고의 설명을 확인하세요.'),
   ('다음 모집을 기다리는 동안 준비할 것','계약 당사자와 주소, 실제 월세 이체 내역이 연결되는지 확인해 두세요. 관리비가 포함된 금액을 내고 있다면 순수 월세와 구분할 수 있는 자료가 도움이 돼요. 서류의 발급일과 제출 방식은 다음 공고에서 바뀔 수 있으므로 모든 서류를 미리 발급하기보다 필요한 목록부터 정리하는 편이 좋아요.')],
  'example_title':'지급 규모를 이해하는 가상 예시',
  'example':[('인정 월세 15만원','지원이 인정된다면 월 최대 지원 상한보다 낮은 실제 인정 월세 범위에서 판단'),('월세 30만원 + 관리비 5만원','월 35만원 전액이 아니라 공고의 월 최대 20만원 및 제외 비용 기준 확인'),('최대 지원 규모','20만원 × 24회 = 480만원은 모든 회차와 월 최대액을 충족한 경우의 상한 예시')],
  'example_note':'자격과 실제 지급은 담당 기관이 결정해요. 480만원을 누구나 한 번에 받는다는 뜻은 아니며 이전 지급 회차도 확인해야 해요.',
  'checklist':['2026년 정기 모집 마감 및 추가·차기 공고 확인','공고의 신청 가능 출생연도와 무주택 요건 확인','청년가구·원가구 소득과 재산, 예외 규정 확인','임대차계약서와 월세 이체 증빙 정리','과거 지원 회차와 중복 제한 확인'],
  'faq':[('부모님과 같이 살면 월세 지원을 받을 수 있나요?','이 글의 2026년 청년월세 안내는 부모와 별도 거주하는 무주택 청년을 대상으로 해요. 다른 지역의 별도 사업은 조건이 다를 수 있으므로 해당 공고를 따로 확인해야 해요.'),('2026년 10월에도 지금 신청할 수 있나요?','확인한 정기 모집 공고는 5월 29일에 마감됐어요. 추가 모집이나 다음 정기 신청 여부는 복지로의 최신 공고에서 확인해 주세요.'),('월세 세액공제와 청년월세 지원은 같은 제도인가요?','달라요. 월세 지원은 지원금 지급 제도이고 월세 세액공제는 세금 정산 항목이에요. 각각의 대상과 중복·조정 조건을 확인해야 하며 같은 지출의 혜택을 임의로 합산하면 안 돼요.')]},
 'guide-health-refund': {
  'reader':'병원비를 많이 지출했거나 공단에서 환급 안내를 받았는데 어떤 금액이 대상인지 헷갈리는 분을 위한 글이에요.',
  'extra':[
   ('영수증에서 먼저 구분할 항목','병원 결제액에는 건강보험 급여 본인부담금과 비급여 등 성격이 다른 비용이 섞일 수 있어요. 총액만 모아서 상한액을 빼면 대상이 아닌 비용까지 환급금으로 부풀릴 수 있어요. 공단이 인정한 상한제 대상 본인부담금과 실제 결제 총액을 구분하는 것이 먼저예요.'),
   ('진료연도와 환급 안내를 받은 연도','안내문을 받은 해가 곧 진료비가 발생한 해라고 생각하면 다른 상한액을 적용할 수 있어요. 진료연도를 기준으로 내역과 상한액을 맞추고 요양병원 입원일수 등 적용 구분도 확인하세요. 가족 여러 명의 의료비와 상한액을 한 사람의 금액처럼 섞지 않아야 해요.'),
   ('이미 받은 돈이나 다른 지원이 있다면','상한제 사전급여나 이미 지급된 초과금이 있다면 다시 받을 금액에서 조정해야 해요. 다른 의료비 지원과의 중복 및 사후 확인에 따른 정산도 있을 수 있어요. 계산기 결과가 공단 안내와 다르면 영수증 총액보다 산정 대상액·기지급액·진료연도를 먼저 대조해 보세요.')],
  'example_title':'진료비 총액 대신 상한제 대상액으로 계산하는 예시',
  'example':[('가상의 상한제 대상액','350만원. 총 병원 결제액과는 별도 금액'),('가상의 개인별 상한액','150만원. 실제 연도별 분위 상한액을 뜻하지 않음'),('기지급액이 없는 경우','350만원 − 150만원 = 초과분 200만원'),('기지급액이 50만원인 경우','200만원 − 50만원 = 잔여 초과분 150만원')],
  'example_note':'단순 계산 방법을 설명하는 가상 사례예요. 지급 결정은 공단 확인 내역과 다른 지원의 조정 결과에 따라 달라질 수 있어요.',
  'checklist':['진료연도와 대상자 이름 확인','공단 인정 본인부담금 및 제외 비용 확인','같은 진료연도의 개인별 상한액 확인','기지급·공제액과 다른 의료비 지원 내역 확인','공식 사이트에서 실제 환급 조회 및 신청'],
  'faq':[('영수증의 급여 항목은 모두 포함되나요?','건강보험 급여 항목에도 상한제에서 제외되는 비용이 있을 수 있어요. 단순히 영수증의 급여 합계를 사용하기보다 공단 산정 대상액을 확인하는 것이 좋아요.'),('소득이 바뀌면 과거 진료비의 상한액도 바로 바뀌나요?','현재 소득을 과거 진료연도에 그대로 대입해서는 안 돼요. 해당 연도에 공단이 적용한 보험료 구간과 상한액을 확인해 주세요.'),('머니패스 결과와 공단 결과가 다르면 무엇이 기준인가요?','공단의 지급 심사·조회 결과가 기준이에요. 이 도구는 입력한 숫자의 초과분을 계산하므로 상한액이나 대상액이 다르면 결과도 달라져요.')]},
 'guide-retirement-planning': {
  'reader':'퇴사 후 받을 돈과 세금, 앞으로의 연금 수령을 함께 살펴보되 서로 다른 계산을 구분하고 싶은 분을 위한 글이에요.',
  'extra':[
   ('퇴사 정산은 지급 항목부터 나눠 보세요','마지막 월급, 미사용 연차수당, 퇴직금은 같은 돈이 아니에요. 각각의 산정 기간과 과세 방식, 지급 요건을 따로 확인한 뒤 현금흐름으로 모아 보는 편이 좋아요. 실업급여까지 퇴직 시 확정 수령하는 금액에 미리 더하면 생활비 계획이 어긋날 수 있어요.'),
   ('퇴직금을 IRP로 받을 때','세금을 공제한 일시금 수령 가정과 IRP로 이전되는 금액은 서로 달라요. 세금이 이연된 경우와 실제 인출 시점의 과세를 구분해야 해요. 이 계산기의 세후 퇴직금 숫자를 IRP 계좌에 들어와야 할 잔액으로 바로 대조하지 마세요.'),
   ('국민연금 비교에서 놓치기 쉬운 시간','5년 늦게 받으면 월액은 늘지만 5년 동안 받지 않은 돈도 있어요. 같은 90세까지의 누적액처럼 종료 시점을 맞춰야 두 선택의 기간 차이를 볼 수 있어요. 다만 단순 누적에는 물가·세금·추가가입·현재가치가 빠져 있으므로 개인에게 맞는 선택까지 자동으로 정해주지는 않아요.'),
   ('연말정산 숫자를 읽는 순서','먼저 공제 대상 지출과 납입액을 확인하고, 다음으로 소득공제와 세액공제를 나눠 보세요. 마지막으로 결정세액과 원천징수한 기납부세액을 비교해야 환급 여부를 알 수 있어요. 공제 가능 금액이 커도 차감할 세금이 충분하지 않으면 같은 금액을 돌려받지 못해요.')],
  'example_title':'월액 100만원·정상 65세·90세까지의 단순 연금 비교',
  'example':[('정상 수령','100만원 × 25년 × 12개월 = 3억원'),('5년 조기','70만원 × 30년 × 12개월 = 2억 5,200만원'),('5년 연기','136만원 × 20년 × 12개월 = 3억 2,640만원')],
  'example_note':'조기 자격 인정·전액 연기 및 일정 월액을 가정했어요. 세금·물가·추가가입·부양가족연금과 현재가치는 제외한 비교예요.',
  'checklist':['마지막 월급·연차수당·퇴직금 구분','퇴직금의 근무일수·평균임금·통상임금 대조','IRP 이체와 일시금 수령의 세금 처리 구분','공단에서 정상 개시 예상 연금액 확인','세액공제 가능액과 실제 환급액 구분'],
  'faq':[('퇴직금 세금은 누구나 3.5% 정도인가요?','고정 비율로 정해져 있지 않아요. 퇴직소득금액과 세법상 근속연수, 각종 공제와 기본세율을 순서대로 적용해야 해요.'),('연금저축 공제액 99만원이면 99만원 환급인가요?','차감할 세금이 충분하고 다른 조건을 충족할 때의 공제 효과예요. 실제 환급액은 기납부세액과 결정세액 차이이므로 그 숫자만으로 확정할 수 없어요.'),('다른 계산기 결과를 한 번에 더해도 되나요?','원금·수당·세금 공제·환급을 구분한 뒤 서로 중복되거나 이미 반영된 항목이 없는지 확인해야 해요. 성격이 다른 최대금액을 단순 합산하면 실제로 쓸 수 있는 돈보다 크게 보일 수 있어요.')]},
}

ADDITIONAL_GUIDES = [
 dict(id='guide-earned-income-credit',title='퇴사 후에도 확인하는 근로·자녀장려금 신청 기준',category='세금',summary='현재 직업보다 귀속연도의 가구소득과 재산이 중요해요. 가구 구분·신청 방식·감액 조건을 나눠 확인해 보세요.',sources=['earnedguide','earnednotice'],sections=[
  ('지금 무직이라는 이유로 확인을 멈추지 마세요','근로·자녀장려금은 해당 귀속연도의 인정 소득과 가구요건을 확인하는 제도예요. 올해 퇴사했더라도 작년에 근로·사업·종교인 소득 등이 있었다면 신청 안내를 확인할 필요가 있어요. 현재 상황만 보고 무조건 대상이거나 대상이 아니라고 판단하면 안 돼요.'),
  ('단독·홑벌이·맞벌이 가구는 무엇이 다른가요?','가구 구분에는 배우자, 부양자녀와 직계존속의 존재 및 소득요건 등이 반영돼요. 같이 산다는 사실이나 부부 모두 일을 한다는 표현만으로 정하지 말고 국세청의 해당 연도 가구 정의를 확인해야 해요. 2025년 귀속 정기 안내의 근로장려금 총소득 기준은 단독 2,200만원·홑벌이 3,200만원·맞벌이 4,400만원 미만이에요.'),
  ('소득과 재산을 따로 확인하세요','2025년 귀속 정기 안내에서는 가구원 전체 재산 합계 2억 4천만원 미만 등의 조건을 확인해요. 부채를 차감하지 않는 기준도 있으므로 대출이 많다는 이유만으로 심사 재산이 작다고 단정하면 안 돼요. 사업자는 단순 매출이 아니라 업종별 조정률 등을 적용하는 소득 기준도 확인해야 해요.'),
  ('정기·반기·기한 후 신청을 구분하세요','정기신청과 반기신청의 대상 소득·정산 방식은 달라요. 사업소득이 있는 경우와 근로소득만 있는 경우를 구분해서 공식 안내를 확인하세요. 기한 후 신청 가능 기간과 감액 여부도 해당 공고를 기준으로 봐야 해요. 같은 귀속연도에 신청 방식만 바꿔 중복으로 받을 수 있는 제도로 이해하면 안 돼요.'),
  ('신청 후 지급액이 달라질 수 있는 이유','최대 지급액은 모든 신청자에게 지급되는 정액이 아니에요. 가구유형과 총급여액 등, 재산 구간, 신청 시기, 기존 지급·체납충당 등 정산 요소에 따라 달라질 수 있어요. 홈택스 계산왕 연계 결과도 최종 지급 결정과는 구분해야 해요.')]),
 dict(id='guide-employment-support',title='국민취업지원제도: 구직촉진수당과 신청 준비 순서',category='취업',summary='Ⅰ·Ⅱ유형의 차이부터 소득·재산 확인, 상담과 구직활동, 다른 수당과의 참여 제한까지 정리했어요.',sources=['employment'],sections=[
  ('취업지원서비스와 현금수당을 구분하세요','국민취업지원제도는 일자리를 찾는 과정의 상담과 취업지원서비스 등을 제공해요. Ⅰ유형 구직촉진수당과 Ⅱ유형 지원 내용이 같지는 않아요. 취업지원서비스에 참여할 수 있다는 것과 월 수당을 받을 수 있다는 것을 별도로 확인해야 해요.'),
  ('월 60만원은 어떤 경우의 금액인가요?','확인한 고용24 안내는 Ⅰ유형 구직촉진수당을 월 60만원씩 6개월 지급하는 구조를 설명해요. 수급자격 인정과 취업활동계획 이행 등이 전제이며, 부양가족에 따른 추가수당은 별도 기준을 확인해야 해요. 360만원을 신청 즉시 한 번에 받는다는 뜻은 아니에요.'),
  ('가구소득·재산과 취업경험을 함께 확인하세요','개인 월급이 없다고 자동으로 대상이 되는 것은 아니에요. 가구단위 소득과 재산, 최근 취업경험, 청년 선발형 등 유형별 요건을 확인해야 해요. 재학·근로·사업 상태도 세부 요건에 영향을 줄 수 있으니 간단한 상태 선택만으로 배제하거나 확정하지 않는 것이 좋아요.'),
  ('신청 이후에는 상담과 계획 이행이 이어져요','고용24 또는 고용센터 안내로 신청한 뒤 담당자와 취업활동계획을 수립해요. 상담·훈련·입사지원 등 정해진 활동을 이행하고 해당 회차의 보고·지급 신청 절차를 확인해야 해요. 연락을 못 받거나 활동을 이행하기 어려운 일이 생기면 혼자 판단해 중단하기보다 담당자에게 확인하세요.'),
  ('실업급여 등 다른 지원을 받고 있다면','다른 수당·직접일자리 참여와의 중복 또는 참여 제한은 공식 안내에서 먼저 확인해야 해요. 받을 수 있어 보이는 두 제도의 최대액을 동시에 받을 금액으로 더하지 마세요. 신청할 때 현재 참여 중인 제도와 최근 지급 이력을 빠짐없이 알려주는 것이 좋아요.')]),
 dict(id='guide-youth-future-savings',title='청년미래적금과 청년도약계좌, 무엇을 구분해야 할까요?',category='저축',summary='신규 상품을 찾는 분과 기존 계좌 가입자가 볼 정보를 나눴어요. 3년 만기·월 납입한도·기여금 구조부터 확인해 보세요.',sources=['future'],sections=[
  ('두 상품의 안내를 섞어 읽지 마세요','청년도약계좌는 신규 가입 종료 안내와 기존 가입자의 계좌 관리가 중심이에요. 새로 가입할 상품을 찾고 있다면 서민금융진흥원의 청년미래적금 공식 안내를 따로 확인해야 해요. 상품명이 비슷해도 만기·한도·우대형 조건과 가입 일정이 같지 않아요.'),
  ('청년미래적금의 기본 구조','공식 안내는 3년 만기, 월 최대 50만원 자유납입과 일반형 6%·우대형 12% 정부기여금 및 이자소득 비과세 구조를 설명해요. 만 19~34세와 병역이행기간 인정, 개인·가구소득 및 상품유형 요건 등을 함께 확인해야 해요. 모든 가입자가 우대형 기여율을 받는 것은 아니에요.'),
  ('기여율과 은행 금리는 다른 숫자예요','정부기여금 비율은 납입금에 매칭되는 지원 기준이고 은행 연 이자율은 이자를 계산하는 기준이에요. 기여율 6%와 은행 금리를 단순히 더해 수익률로 표시하면 납입 시점과 잔액의 차이를 놓칠 수 있어요. 원금·정부기여금·은행이자를 각각 나누어 비교하는 편이 정확해요.'),
  ('가입 가능성과 우대형 유지를 확인하세요','가입 시 소득 확인과 별도로 우대형의 근속 등 유지 조건이 있을 수 있어요. 내 현재 직장이 중소기업에 해당하는지, 어떤 유형으로 심사되는지, 이직·퇴직할 때 기여금 처리가 어떻게 달라지는지는 공식 상품 안내를 확인해야 해요. 최대 혜택만 보고 확정된 수익처럼 계획하지 마세요.'),
  ('기존 청년도약계좌를 갖고 있다면','두 상품이 다르다는 사실만으로 무조건 해지·전환하는 것이 유리하지는 않아요. 이미 받은 기여금과 앞으로의 금리, 남은 기간, 전환 가능한 시기와 조건을 확인해야 해요. 일반 중도해지와 특별중도해지·연계가입을 구분하고 처리 순서를 가입 은행에 먼저 문의하세요.')]),
 dict(id='guide-telecom-refund',title='통신 미환급액 조회: 번호이동 뒤 남은 돈 확인하기',category='생활',summary='누구나 정해진 금액을 받는 환급이 아니에요. 과오납·보증금 등 실제 내역과 조회 가능한 통신사를 확인해 보세요.',sources=['telecom'],sections=[
  ('통신 미환급액은 어떤 돈인가요?','통신서비스를 해지하거나 번호이동한 뒤 사후 정산에서 확인된 과오납 요금, 선납금 등 돌려받지 않은 금액을 뜻해요. 이용자 모두에게 일괄 지급하는 지원금이 아니므로 조회 결과가 없다면 받을 금액도 없을 수 있어요.'),
  ('공식 조회에서 확인할 것','스마트초이스의 통신 미환급액 안내에서 조회 가능한 통신사와 서비스 유형을 확인하세요. 확인한 안내에는 KT·SK텔레콤·LG유플러스·SK브로드밴드 등이 표시돼 있어요. 모든 알뜰폰이나 공과금이 이 한 화면에 포함된다고 해석하지 말고 해당 사업자의 공식 안내도 확인해야 해요.'),
  ('조회가 안 될 때 먼저 볼 것','서비스 안내의 조회 가능 시간은 09시~20시이며 일요일·공휴일 제외 조건이 있어요. 실제 화면의 점검·이용시간 공지도 함께 확인하세요. 과거에 서비스를 이용한 통신사와 조회 대상이 맞는지도 확인하고, 필요하면 해지한 통신사의 공식 사이트로 문의할 수 있어요.'),
  ('조회와 환급신청은 별도 단계예요','공식 안내에서는 회원가입 없이 조회할 수 있지만 환급액이 있는 경우 신청에 회원가입 등이 필요할 수 있다고 설명해요. 금액을 확인한 뒤 안내된 공식 절차로 신청해야 하며, 조회했다고 자동 입금된다고 생각하지 마세요.'),
  ('개인정보는 공식 사이트에 직접 입력하세요','이 사이트에는 이름·주민등록번호·환급계좌를 입력하지 않아요. 링크를 따라갈 때 주소를 확인하고 스마트초이스나 통신사 공식 화면에서 직접 진행해 주세요. 문의 이메일에 신분증이나 금융인증정보를 보내는 방식으로 환급을 신청하는 서비스가 아니에요.')]),
]

