GUIDE_DETAILS['guide-earned-income-credit']['faq'] = [
 ('작년에 일했고 올해는 무직인데 신청할 수 있나요?','현재 무직이라는 사실만으로 배제하지 말고 해당 귀속연도의 소득·가구·재산 기준을 확인해야 해요. 올해 소득과 작년 소득을 같은 금액으로 넣지 않도록 주의하세요.'),
 ('사업 매출을 근로자 연봉과 그대로 비교하나요?','국세청 안내의 사업소득 업종별 조정률 등을 적용하는 총급여액 등 기준을 확인해야 해요. 매출과 소득금액이 같다고 보고 자격이나 지급액을 계산하면 오류가 생길 수 있어요.'),
 ('안내문을 못 받으면 대상이 아닌가요?','안내문 수신 여부만으로 자격이 확정되는 것은 아니에요. 홈택스에서 신청 대상·요건을 확인하고 소득·재산 자료가 실제와 다른 경우 안내 절차를 확인해 보세요.')]
GUIDE_DETAILS['guide-employment-support']['faq'] = [
 ('취업지원서비스와 구직촉진수당을 모두 받을 수 있나요?','유형과 자격에 따라 달라요. 현금수당의 대상과 지급 요건을 취업지원서비스 참여 여부와 분리해 확인해 주세요.'),
 ('재학생·아르바이트 근로자는 모두 제외되나요?','재학 형태, 졸업예정 여부, 근로시간과 소득 등 세부 상황에 따라 달라질 수 있어요. 현재 직업 이름 하나로 확정하지 말고 고용24 유형별 안내나 센터 상담을 이용해 주세요.'),
 ('6개월이 지나면 무조건 360만원을 받은 건가요?','자격 인정과 회차별 활동·지급 요건을 충족한 경우의 기본 수당 규모예요. 미이행·소득신고·지급 제한 등 개인 상황에 따라 실제 지급액은 달라질 수 있어요.')]
GUIDE_DETAILS['guide-youth-future-savings']['example'] = [('월 50만원씩 36개월 납입','본인 원금 합계 18,000,000원'),('일반형 6% 단순 매칭 가정','정부기여금 1,080,000원'),('우대형 12% 단순 매칭 가정','정부기여금 2,160,000원')]
GUIDE_DETAILS['guide-youth-future-savings']['example_title']='매월 최대액을 넣는 경우의 원금·기여금 비교'
GUIDE_DETAILS['guide-youth-future-savings']['example_note']='전 기간 해당 유형의 요건을 충족하는 단순 예시이며 은행이자는 제외했어요. 실제 가입·유지 조건과 지급 조정은 공식 안내를 확인해야 해요.'
GUIDE_DETAILS['guide-youth-future-savings']['faq']=[('청년도약계좌 계산기에 미래적금 조건을 넣어도 되나요?','그렇게 비교하면 안 돼요. 만기와 정부기여금 구조가 다르므로 미래적금은 해당 상품의 공식 계산·안내를 이용해야 해요.'),('매일 신청할 수 있나요?','상시 접수로 가정하지 말고 최신 신청 일정과 취급기관 공지를 확인해 주세요. 이 글은 현재 접수 가능 여부를 실시간으로 조회하지 않아요.'),('소득이 늘면 기여율도 자동으로 바뀌나요?','상품별 심사·유지 규칙이 다를 수 있어요. 도약계좌의 유지심사 설명을 미래적금에 그대로 적용하지 말고 해당 상품의 최신 안내를 확인하세요.')]
GUIDE_DETAILS['guide-telecom-refund']['faq']=[('평균 환급액만큼은 받을 수 있나요?','개인별 실제 미환급 내역이 있어야 해요. 다른 사람이 받은 금액이나 평균치가 자신의 지급액을 보장하지 않아요.'),('조회만 하면 자동으로 신청되나요?','조회와 환급신청은 다를 수 있어요. 실제 미환급액이 확인되면 공식 화면의 계좌 등록·회원가입 등 후속 절차를 확인해 주세요.'),('통신 미환급 조회로 전기·수도요금도 찾나요?','이 글은 통신 미환급액 안내예요. 다른 공과금은 해당 기관의 별도 공식 조회·신청 절차를 확인해야 해요.')]
